"""HTML -> PDF using the locally installed Microsoft Edge / Google Chrome (via Playwright).

Security: pages run with JavaScript disabled and the browser context offline, and every network
request is aborted, so resume content can never reach the internet or execute code.
Efficiency: one headless browser is reused across exports and closed after a period of inactivity.
"""
import asyncio
import logging
import time

log = logging.getLogger("resumelens.pdf")
IDLE_SECONDS = 600
CHANNELS = ("msedge", "chrome", None)  # None = Playwright's bundled Chromium, if installed


class BrowserUnavailable(RuntimeError):
    """No Chromium-based browser could be launched."""


class PdfEngine:
    """Lazily started, shared headless browser."""

    def __init__(self):
        self._lock = asyncio.Lock()
        self._pw = None
        self._browser = None
        self._last_used = 0.0
        self._failed_at = 0.0
        self._reaper: asyncio.Task | None = None

    async def _ensure(self):
        if self._browser and self._browser.is_connected():
            return self._browser
        if self._failed_at and time.monotonic() - self._failed_at < 60:
            raise BrowserUnavailable("browser launch recently failed")
        try:
            from playwright.async_api import async_playwright
        except ImportError as exc:
            raise BrowserUnavailable("playwright not installed") from exc
        self._pw = await async_playwright().start()
        for channel in CHANNELS:
            try:
                # --disable-dev-shm-usage: containers often have a tiny /dev/shm, which crashes Chromium
                kwargs = {"headless": True, "args": ["--disable-extensions", "--no-first-run", "--disable-dev-shm-usage"]}
                if channel:
                    kwargs["channel"] = channel
                self._browser = await self._pw.chromium.launch(**kwargs)
                log.info("PDF engine started with %s", channel or "bundled chromium")
                break
            except Exception as exc:  # try the next browser
                log.debug("cannot launch %s: %s", channel, exc)
        if not self._browser:
            await self._pw.stop()
            self._pw = None
            self._failed_at = time.monotonic()
            raise BrowserUnavailable("no Chromium-based browser found")
        if not self._reaper or self._reaper.done():
            self._reaper = asyncio.create_task(self._reap_idle())
        return self._browser

    async def _reap_idle(self):
        """Close the browser after IDLE_SECONDS without exports (frees ~150 MB RAM)."""
        while True:
            await asyncio.sleep(60)
            if self._browser and time.monotonic() - self._last_used > IDLE_SECONDS:
                async with self._lock:
                    await self._close_locked()
                return

    async def _close_locked(self):
        if self._browser:
            try:
                await self._browser.close()
            except Exception:
                pass
        if self._pw:
            try:
                await self._pw.stop()
            except Exception:
                pass
        self._browser = self._pw = None

    async def warm_up(self):
        """Start the browser in the background so the first export is fast."""
        try:
            async with self._lock:
                await self._ensure()
                self._last_used = time.monotonic()
        except BrowserUnavailable:
            pass

    async def html_to_pdf(self, html: str) -> bytes:
        """Render a self-contained HTML document to A4 PDF bytes."""
        async with self._lock:
            browser = await self._ensure()
            self._last_used = time.monotonic()
            context = await browser.new_context(java_script_enabled=False, offline=True)
            try:
                await context.route("**/*", lambda route: route.abort())
                page = await context.new_page()
                await page.set_content(html, wait_until="load", timeout=20_000)
                return await page.pdf(format="A4", print_background=True, prefer_css_page_size=True)
            finally:
                await context.close()

    async def close(self):
        async with self._lock:
            await self._close_locked()
        if self._reaper:
            self._reaper.cancel()


engine = PdfEngine()
